  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid with the same conjugated tetraene and beta-ionone-like ring system, has an absolute oral bioavailability of approximately 60% (range 36-95%) after oral dosing, supporting high bioavailability for the closely related retinoid amide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a retinoic acid isomer sharing the retinoid backbone, has a systemic bioavailability of about 40%, supporting F >=20% for the query retinoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a lipophilic retinoid ester, has an absolute oral bioavailability of about 40%, indicating that highly lipophilic retinoids can still achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Oral tretinoin bioavailability is estimated at 25-30%, which is still above the 20% threshold and supports the retinoid class being orally bioavailable at the threshold level.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a retinoid amide. Transferable evidence from retinoic acid, isotretinoin, acitretin, and etretinate consistently shows oral bioavailability of roughly 25-60%, all above the F>=20% threshold. No affirmative evidence indicates F<20% for this retinoid scaffold, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself is present in the visible evidence.",
    "The effect of replacing the terminal carboxylate/ester with a p-hydroxyanilide amide on absorption is not directly evidenced; this modification could lower bioavailability, but not enough to predict sub-20% without affirmative data."
  ],
